// Message contract between a host page and the runner iframe.
// Every message carries a `type` prefixed with `pine-runner:`.

export const PROTOCOL_VERSION = 2;

export type ScalarInput = string | number | boolean;

/** Column-oriented OHLCV candles. `time` is the bar open time in milliseconds since epoch. */
export interface RunnerCandles {
  time: number[];
  open: number[];
  high: number[];
  low: number[];
  close: number[];
  volume: number[];
}

export interface RunRequest {
  type: "pine-runner:run";
  id: string;
  source: string;
  candles: RunnerCandles;
  /** TradingView timeframe string: "1", "5", "60", "240", "D", "W", "M". */
  timeframe: string;
  symbol?: string;
  /**
   * Input overrides keyed by the Pine variable name (`len = input.int(...)` is keyed "len") or by
   * the declaration id (`in_0`) for an input that is not assigned to a variable. Unknown keys and
   * values the input rejects are skipped and reported in `warnings`.
   */
  inputs?: Record<string, ScalarInput>;
  /** Wall-clock budget for the run. The runner terminates the worker when exceeded. */
  timeoutMs?: number;
}

export interface InputMeta {
  id: string;
  varId: string;
  title: string;
  type: string;
  defval: unknown;
  /** The value this run used: the override from `inputs` when one was accepted, else `defval`. */
  value: unknown;
  minval?: number;
  maxval?: number;
  step?: number;
  options?: unknown[];
}

export interface PlotPoint {
  time: number;
  /** Number for series plots, boolean for plotshape/plotchar, number[] for plotcandle/plotbar, null for na. */
  value: number | boolean | number[] | null;
  color?: string;
}

export interface PlotSeries {
  key: string;
  title: string;
  /** PineTS style token such as "line", "style_histogram", "hline", "fill", "shape", "char", "background", "barcolor", "candle". */
  style: string;
  options: Record<string, unknown>;
  points: PlotPoint[];
}

export interface RunResult {
  title: string;
  shortTitle: string;
  overlay: boolean;
  inputs: InputMeta[];
  plots: PlotSeries[];
  /** Final state of label.*, line.*, box.* and table.* objects, as PineTS stores them (x in bar index unless xloc is bar_time). */
  labels: Record<string, unknown>[];
  lines: Record<string, unknown>[];
  boxes: Record<string, unknown>[];
  tables: Record<string, unknown>[];
  warnings: string[];
  /** Original `//@version` when the runner rewrote a v1-v4 script to v5 before running it. */
  upgradedFromVersion: number | null;
  durationMs: number;
}

export interface RunError {
  message: string;
  line?: number;
  column?: number;
}

export interface ReadyMessage {
  type: "pine-runner:ready";
  protocol: typeof PROTOCOL_VERSION;
  pinets: string;
}

export interface RunReply {
  type: "pine-runner:result";
  id: string;
  ok: boolean;
  result?: RunResult;
  error?: RunError;
}

/**
 * Sent while a run is in progress when the script reads another symbol or timeframe
 * (`request.security`). The embedder answers with a DataResponse carrying the same ids.
 */
export interface DataRequest {
  type: "pine-runner:data-request";
  runId: string;
  requestId: string;
  symbol: string;
  /** TradingView timeframe string, as in RunRequest. */
  timeframe: string;
  /** Bar open time bounds in milliseconds, when the script's range is known. */
  from?: number;
  to?: number;
  limit?: number;
}

export interface DataResponse {
  type: "pine-runner:data-response";
  runId: string;
  requestId: string;
  ok: boolean;
  candles?: RunnerCandles;
  error?: string;
}

export type HostToRunner = RunRequest | DataResponse;
export type RunnerToHost = ReadyMessage | RunReply | DataRequest;

export function isRunRequest(value: unknown): value is RunRequest {
  if (!value || typeof value !== "object") return false;
  const m = value as Record<string, unknown>;
  return (
    m.type === "pine-runner:run" &&
    typeof m.id === "string" &&
    typeof m.source === "string" &&
    typeof m.timeframe === "string" &&
    isCandles(m.candles)
  );
}

export function isDataResponse(value: unknown): value is DataResponse {
  if (!value || typeof value !== "object") return false;
  const m = value as Record<string, unknown>;
  return (
    m.type === "pine-runner:data-response" &&
    typeof m.runId === "string" &&
    typeof m.requestId === "string" &&
    typeof m.ok === "boolean" &&
    (m.ok ? isCandles(m.candles) : true)
  );
}

export function isCandles(value: unknown): value is RunnerCandles {
  if (!value || typeof value !== "object") return false;
  const c = value as Record<string, unknown>;
  const columns = ["time", "open", "high", "low", "close", "volume"] as const;
  const lengths = columns.map((name) => (Array.isArray(c[name]) ? c[name].length : -1));
  return lengths[0]! > 0 && lengths.every((length) => length === lengths[0]);
}
